#!/usr/bin/env python3
"""Year 3 Creative Arts Written Core batch 04: movement phrases, dance response, printmaking, collage, First Nations protocol, artists w19-l1 through w24-l2 (12)."""
from arts_support import L, pv, create, VIS, DAN

LESSONS = [
L('s2-arts-y3-w19-l1', DAN, ['a movement phrase', 'beginning, middle, end', 'a motif', 'repetition'],
  "A movement phrase is a short sequence of movements joined together, like a sentence in dance. A phrase has a clear beginning (a starting shape), a middle (the main movements) and an end (a finishing shape you hold). A motif is a small movement idea, such as a swirl of the arm, that you can repeat or change to link a phrase. Repeating a motif makes the dance easy to follow. Plan your phrase on paper using words or stick figures, practise it slowly in a clear space and keep the movements at a comfortable level for your body.",
  "Example: a phrase called 'Sunrise'. Beginning: curl low on the floor. Middle: stretch up slowly (motif: arms rising like a sun), then reach out wide with a slow turn. End: stand tall in a wide star shape and hold for three counts. The rising-arms motif is repeated twice in the middle, so the phrase feels connected and clear.",
  "Plan a four-movement phrase called 'Rain'. Name the beginning shape, two middle movements including a motif and the ending shape.",
  "Strong answer: 'Beginning: stand still, hands above head. Middle: fingers wiggle down (motif) twice, then a quick jump into a puddle. End: curl low and hold.' It has a clear start and finish and one motif repeated.",
  "Thinking that a movement phrase is just a random group of favourite moves. A phrase has a clear beginning, middle and end, and the movements are chosen and joined to show one idea.",
  "Make a phrase of five movements about a weather idea of your choice (wind, storm, snow). Write the beginning, middle and end shapes, mark a motif and repeat it. Practise until you can perform it three times the same, then teach it to a family member."),
L('s2-arts-y3-w19-l2', DAN, ['composing', 'a short dance', 'a choice', 'a changing element'],
  "Composing a dance means making your own sequence and choosing how it looks. Start with a theme, such as an animal or a feeling. Join two or three phrases and decide how to change an element, for example doing the same phrase low and then high, or slow and then fast. Write a plan showing the order, then rehearse until you can remember it. Say why you made each choice. Always compose in a clear, safe space, and you may create the dance with hands only if standing is not possible.",
  "Example: Cleo composes a 30-second dance about a butterfly. Phrase 1: small, curled, slow movement (cocoon). Phrase 2: arms stretch wide with a slow turn (wings open). Phrase 3: light skipping steps along a curved pathway (flying). She changes the time from slow to quick and the level from low to high. Her plan lists these as 1, 2, 3.",
  "Compose a three-phrase dance about a robot waking up. Name each phrase, and say which element changes from phrase to phrase.",
  "Strong answer: 'Phrase 1: still and low (asleep). Phrase 2: slow, stiff arm movements (switching on). Phrase 3: quick, sharp steps around the room (working). The time changes from slow to fast and the energy changes from heavy to sharp.' Each phrase has a purpose.",
  "Believing that you should copy a dance you have seen. Composing means making your own choices, though you can take inspiration from other dances and give credit.",
  "Compose a 30-second dance with three phrases and a title. Write the plan with a drawing of each shape, say which element changes, rehearse it five times and perform it for family. Write one choice you would change."),
L('s2-arts-y3-w20-l1', DAN, ['a performance', 'a respectful audience', 'a dance review', 'a dance element'],
  "When you perform a dance, you share it with an audience. Start in a clear still shape, perform your whole phrase with focus and finish in a held shape. The audience watches quietly, claps and then gives feedback. To respond to a dance, first describe what you saw using the elements (body, space, time, energy), then say what it made you think or feel with a reason. For example, 'The slow, low movements made me feel sleepy because the energy was heavy.' Be kind and talk about the dance, not the dancer.",
  "Example: After watching Lina's dance, Omar says, 'I saw big, slow turns at a high level and then a quick drop low. It felt dramatic because the speed changed suddenly.' He described body, space and time, then gave a reason for his feeling. Lina says, 'Thank you.' Her wish is to hold the final shape longer.",
  "Describe a dance you saw (or imagine one) using two elements, and say how it made you feel with a reason.",
  "Strong answer: 'The dancer used quick, sharp steps (time and energy) and stayed at a low level (space). It felt tense because the movements were fast and sudden.' It describes first, then gives a reasoned response.",
  "Thinking that responding to a dance means saying whether you like the dancer. A response talks about what is in the dance, the elements and the effect, and not about the person.",
  "Watch a short dance video with an adult or perform one for family. Write a response with a description of two elements, a feeling and a reason. Then write one star and one wish for the dance and read them kindly to a family member."),
L('s2-arts-y3-w20-l2', DAN, ['a dance showcase', 'a rehearsal plan', 'a reflection', 'a next step'],
  "A dance showcase is a performance of your best work at the end of a unit. Prepare by choosing a piece, rehearsing it several times and planning the start and the end shapes. Name the dance elements you used so the audience knows what to watch for. After the showcase, reflect on what went well, which elements were most effective and what you will do next time. Keep your feedback specific and kind. If a performance is not possible, you may describe or draw the dance and give a talk.",
  "Example: Ravi's showcase has a short introduction: 'My dance is called Wind. I use quick, high movements and slow, low ones.' He performs, holds his final shape and bows. His reflection reads: 'Star: I stayed in time with the music. Star: my changes of level were clear. Wish: next time I will stretch my arms more.'",
  "Write a two-sentence introduction for a dance you could perform, naming the title and two elements.",
  "Strong answer: 'My dance is called Waves. It uses slow, curved movements at a low level and quick, high jumps for the big wave.' The introduction names the title and two elements, which helps the audience watch closely.",
  "Believing that a showcase means including every movement you know. It is better to show a clear, well-rehearsed piece that uses a few elements with confidence.",
  "Rehearse your best dance from this unit and perform it for family. Introduce it with the title and two elements. Ask for two stars and a wish, and write a reflection with one thing to keep and one thing to practise next."),
L('s2-arts-y3-w21-l1', VIS, ['a print', 'a printing plate', 'ink or paint', 'repeating'],
  "Printmaking makes copies of an image. A printing plate holds the design, such as a piece of foam, a potato half or a found object like a leaf. You add a thin layer of paint or ink to the plate, press it onto paper and lift it, and the image appears reversed, like a mirror. You can repeat the same print many times to make a pattern. Use only a thin layer of paint, press evenly and keep your workspace covered. An adult should cut any firm materials such as potatoes.",
  "Example: Nina draws a fish on a foam tile with a pencil, pressing grooves in the foam. She rolls blue paint on the tile, lays paper on top, rubs gently and lifts it. The fish print appears with the grooves showing as white lines, and the fish faces the opposite direction to the plate. She repeats the print four times in a row to make a shoal.",
  "You want to print the letter 'S' on a card. Explain what you need to do to the plate so the print looks the right way round, and how much paint to use.",
  "Strong answer: 'I need to carve or draw a reversed S on the plate, because the print flips it. I will use a thin layer of paint, because too much will blur the lines.' Prints are mirror images of the plate, and thin paint gives clear lines.",
  "Thinking that thick paint gives a stronger print. Too much paint squashes out, fills the details and makes a smudged print, so a thin, even layer works best.",
  "Make four prints using a leaf, a sponge or a potato (cut by an adult). Test thin and thick paint and write which worked better. Arrange your best prints in a repeating pattern and label the pattern. Cover your table and wash hands afterwards."),
L('s2-arts-y3-w21-l2', VIS, ['a foam tile', 'a roller', 'a clean print', 'a drying space'],
  "To make a print, plan the design on paper first, then draw it lightly into the foam tile with a blunt pencil so the lines are pushed in. Roll a thin layer of paint evenly across the tile, place the paper on top, press with a clean hand or a clean roller, and peel it off slowly. Reprint by re-rolling the paint. Lay prints flat to dry and clean the tile and tools straight away. Press, don't slide, so the print does not smudge.",
  "Example: Max designs a sun with rays. He pushes the lines into the foam. He rolls yellow on the tile, presses it onto card and lifts it slowly. The first print is light, so he adds a little more paint and prints again. The second print is bold and clear, so he makes a row of four and lays them flat to dry on a tray.",
  "Your first print is patchy and some lines are missing. Name two changes you could make for the next print.",
  "Strong answer: 'Roll the paint more evenly over the whole tile, and press with the flat of my hand all over so the paper touches every part.' Patchy prints come from uneven paint or uneven pressure.",
  "Thinking that sliding the paper makes it stick better. Sliding blurs and smudges the print, so press down firmly without moving the paper.",
  "Design and make a foam tile print with a simple picture of your choice, then print it at least four times. Make one in a second colour. Write one sentence about what the repeated prints look like together and what you would change."),
L('s2-arts-y3-w22-l1', VIS, ['a collage', 'layering', 'overlapping', 'a background'],
  "A collage is an artwork made by gluing pieces of paper, fabric or other flat materials onto a surface. Layering means placing pieces on top of each other, so overlapping shapes create depth. Start with a background layer, then add bigger shapes in the middle layer and small details on top. Tear paper for soft edges and cut it for crisp edges. Plan your layout before gluing and use a thin layer of glue. Pieces that overlap look closer to the viewer, which helps make the picture feel three-dimensional.",
  "Example: Ella's collage of a pond. Layer 1: blue paper background. Layer 2: green torn paper lily pads, some overlapping. Layer 3: a small cut-out yellow frog sitting on top of one pad. The frog looks closest because it is on top, and the torn edges of the pads look soft like leaves. She plans the layout by moving the pieces before gluing.",
  "Plan a collage of a night sky over a town. Say what goes in layer 1, layer 2 and layer 3, and which edges you would tear or cut.",
  "Strong answer: 'Layer 1: dark blue background. Layer 2: black cut-out houses along the bottom. Layer 3: small yellow cut-out windows and a torn white paper moon. Cut for crisp houses and tear for the soft moon.' Overlapping creates depth.",
  "Believing that covering all the paper with glue will make pieces stick better. Too much glue wrinkles and soaks the paper, so use a thin layer and press down.",
  "Collect magazine pages, wrapping paper or coloured scraps. Plan a three-layer collage of a landscape, move the pieces before gluing, then glue. Label which pieces are torn and which are cut and say how overlapping helped the depth."),
L('s2-arts-y3-w22-l2', VIS, ['a texture collage', 'a focal point', 'balance', 'a finished edge'],
  "To make a collage, choose a focal point, which is the main thing you want the viewer to look at, and make it larger or brighter than the rest. Add textured materials such as corrugated card, scrunched tissue or fabric so the collage feels different to touch. Balance the picture by spreading shapes and colours so one side does not feel heavier than the other. Leave a small border and press everything down flat. Scissors should be used carefully and put away after use.",
  "Example: Sam makes a collage of a rooster. The focal point is a big, bright red-and-orange tissue paper tail. He uses scrunched tissue for the feathers (texture) and smooth yellow paper for the beak. A small green hill sits on the left and a tree on the right to balance. He leaves a white border and presses all the pieces flat.",
  "Choose a focal point and a textured material for a collage of a lion, and say how you would balance the picture.",
  "Strong answer: 'Focal point: the big orange mane made from scrunched tissue paper for a fluffy texture. Balance: a tall tree on the left and a rock on the right.' A large, bright focal point attracts the eye, and balanced objects keep the picture steady.",
  "Thinking that every piece in a collage should be the same size and colour. Variety in size and colour, with one main focal point, makes the collage more interesting.",
  "Make a collage of an animal using at least three different textures and a clear focal point. Draw a plan first and write what balances the picture. Give it a title and explain your focal point to someone at home."),
L('s2-arts-y3-w23-l1', VIS, ['First Nations art', 'respect', 'permission', 'a published source'],
  "First Nations art is created by Aboriginal and Torres Strait Islander peoples and carries stories, knowledge and connection to Country. Some designs, symbols and stories belong to particular families or communities and may be sacred or restricted. This lesson is about respectful looking, not copying. Look at artworks from a published, classroom-approved source such as a school library book, a gallery website chosen by your teacher, or an artwork shared by local Aboriginal educators. Describe what you see and ask what the artwork shows, who made it and what Country it belongs to. Do not guess the meaning of symbols, and do not retell stories that are not yours to tell.",
  "Example: a teacher shows a published artwork and its caption from a library book. Student A describes: 'I see curved lines, many dots and earthy colours.' Student B reads the caption: the name of the artist, the Country and the title. A good question is, 'What can you tell us about this artwork?' because it asks the artist's own source, whereas guessing 'this circle means a waterhole' might be wrong and disrespectful.",
  "You see an artwork with dots and circles in a classroom book. Write two respectful questions to ask a local Aboriginal educator and one thing you should not do with the symbols.",
  "Strong answer: 'Who made this artwork and what Country is it from? Can you share what it means, if it is okay to share?' And 'I should not copy the symbols or guess their meanings.' Asking the artist's community and using published sources shows respect.",
  "Believing that all dots and symbols in Aboriginal art can be copied or that they all mean the same thing. Each artwork belongs to its artist and community, and meanings differ between peoples, so we ask, listen and do not guess.",
  "With an adult, find an artwork in a school library book or an approved gallery site. Write its title, artist, Country, what you see and a respectful question. Do not copy any design. If you can, ask a local Aboriginal educator or Elder through your school how to learn more, and write down what you were told, giving credit."),
L('s2-arts-y3-w23-l2', VIS, ['a respectful plan', 'your own story', 'acknowledging Country', 'permission'],
  "A respectful class activity does not copy First Nations designs or sacred symbols. Instead, you can make your own artwork about your own place and story, and show respect by acknowledging whose Country you are on and by crediting any artwork that inspired you. Create original symbols for your own story, such as your family, home or favourite place, and explain them in your own words. If your school wants to work with First Nations art, ask local Aboriginal educators or Custodians for guidance and use only the published materials they or your teacher have approved. If you do not know whether something is allowed, choose a different idea.",
  "Example: Rosa wants to make a symbol story about her family's picnic place. She invents her own symbols: a wavy blue line for the creek, a green triangle for the tent and four small circles for her family. She writes a key. She adds, 'This is my story and not a First Nations design. I live on the Country of the local Aboriginal people.' She does not use sacred or copied symbols.",
  "Plan a symbol story about your own home using three original symbols, and write a key. Say one thing you will not do to stay respectful.",
  "Strong answer: 'Square for my house, a zigzag for the road, and a yellow sun for my garden. Key written beside it. I will not copy any First Nations symbols or paint a Dreaming story.' Original symbols plus a key make a respectful story of your own.",
  "Thinking that using Aboriginal-style dots is a way of showing respect. Copying a style or symbols without permission can disrespect the artists and their communities, so use your own ideas and give credit.",
  "Create a symbol story about your own life with at least four original symbols, a key and a title. Add an acknowledgement of Country sentence if your school uses one. Ask an adult to check that nothing is copied from First Nations art, and write what you would ask local Aboriginal educators."),
L('s2-arts-y3-w24-l1', VIS, ['an artist', 'an artwork', 'a style', 'a technique'],
  "Artists make choices about subject, colour, line and materials, and these choices create a style. Piet Mondrian, a Dutch painter, made paintings using straight black lines in a grid with blocks of red, yellow, blue and white. Henri Matisse, a French artist, made bold paper cut-outs late in his life by cutting painted paper into shapes. When you study an artist, look for their technique, which is how they made the work, and the effect it has. Name the artist, title, materials and an element they used, and give your own response with a reason.",
  "Example: Looking at a Mondrian-style grid, Pia says: 'The artist used thick black lines and large blocks of red, blue and yellow. The straight lines make it feel neat and balanced, and the red block draws my eye first.' She names the technique and the effect. For Matisse she says: 'The cut-out shapes are curvy and bold and feel playful.'",
  "Compare a grid painting made of straight black lines with a paper cut-out of curvy shapes. Name one technique each and its effect.",
  "Strong answer: 'The grid uses straight lines and primary colours, so it feels ordered and calm. The cut-out uses curvy cut shapes and bright colours, so it feels playful.' Each answer names the technique and the effect.",
  "Thinking that artists all make art the same way. Every artist makes different choices, and looking closely at their technique helps us see how they made their work and why it looks that way.",
  "Choose two artists from a library book or a gallery website with an adult. For each, write the name, an artwork title, one technique and one element. Compare them in three sentences and give a reason for your favourite. Do not copy the whole artwork."),
L('s2-arts-y3-w24-l2', VIS, ['inspiration', 'in the style of', 'crediting an artist', 'my own version'],
  "Artists often take inspiration from other artists, but they do not copy. To respond to an artist, choose one idea, such as Mondrian's primary colour blocks or Matisse's cut shapes, and use it in your own subject. Make your own version by changing the subject, the colours or the arrangement. Write a short note crediting the artist, such as 'Inspired by Henri Matisse's paper cut-outs'. Reflect on what you learned about the artist's technique and what you changed. Respecting artists means giving them credit and not pretending their ideas are completely yours.",
  "Example: Ahmed is inspired by Matisse. He cuts paper into curvy shapes in blue and green and arranges them into a sea scene with fish, seaweed and a shell. His label says: 'Sea Creatures. Inspired by Henri Matisse's paper cut-outs. I cut my shapes freehand and used cool colours.' His subject, colours and arrangement are his own.",
  "Plan an artwork inspired by Mondrian that is about your bedroom. Say which idea you will use, what you will change and how you will credit him.",
  "Strong answer: 'I will use straight black lines and colour blocks but arrange them like my bedroom window, with my favourite colours. Label: Inspired by Piet Mondrian.' Using the technique with a new subject and crediting the artist shows respect.",
  "Believing that copying exactly is the best way to respect an artist. Respect means learning from the technique, making your own version and crediting the artist.",
  "Make an artwork inspired by an artist you studied, using a new subject. Write a label with the title, materials, 'inspired by' credit and a sentence about your changes. Share it and explain what you learned from the artist."),
]

VISUALS = {
 's2-arts-y3-w19-l1': [pv('Beginning','curl low, hold','Middle','arms rise (motif), turn','Parts of a movement phrase.','Start, move, finish.'),
  pv('Motif','small arm swirl','Repeat','twice in the middle','A repeated motif.','Repeat to link.')],
 's2-arts-y3-w19-l2': [pv('Phrase 1','curled and slow','Phrase 3','light skips, high','Phrases in a composed dance.','Join phrases.'),
  pv('Time','slow to quick','Level','low to high','Changing elements in a dance.','Change one element.')],
 's2-arts-y3-w20-l1': [pv('Perform','start shape, dance, hold','Audience','watch quietly, then clap','Performing and watching.','Respect the dancer.'),
  pv('Describe','quick steps, low level','Respond','tense because it is sudden','Describing and responding to dance.','Describe, then respond.')],
 's2-arts-y3-w20-l2': [pv('Intro','title and two elements','Perform','hold the final shape','A dance showcase.','Introduce clearly.'),
  pv('Reflect','star, star, wish','Next','stretch arms more','A dance reflection.','Plan a next step.')],
 's2-arts-y3-w21-l1': [pv('Plate','design pressed in foam','Print','image appears reversed','Plate and printed image.','A print is a mirror.'),
  pv('Thin paint','clear lines','Thick paint','smudged lines','Thin and thick paint.','Thin layers print clearly.')],
 's2-arts-y3-w21-l2': [pv('Roll','even thin paint','Press','flat hand, no sliding','Rolling and pressing.','Press, do not slide.'),
  pv('Patchy','uneven paint','Clear','even paint and pressure','Patchy and clear prints.','Fix the paint and press.')],
 's2-arts-y3-w22-l1': [pv('Layer 1','blue background','Layer 3','small frog on top','Collage layers.','Background to detail.'),
  pv('Torn edge','soft, like leaves','Cut edge','crisp, like buildings','Torn and cut edges.','Tear or cut on purpose.')],
 's2-arts-y3-w22-l2': [pv('Focal point','big red tissue tail','Texture','scrunched tissue feathers','A focal point and texture.','Draw the eye.'),
  pv('Balance','tree left, rock right','Border','small white edge','Balance in a collage.','Spread the weight.')],
 's2-arts-y3-w23-l1': [pv('Ask','who, which Country, meaning','Do not','guess or copy symbols','Respectful questions.','Ask, listen, credit.'),
  pv('Source','published and approved','Local','ask local educators','Approved sources.','Use approved sources.')],
 's2-arts-y3-w23-l2': [pv('My symbols','square house, zigzag road','Key','a list of what each means','Original symbols and a key.','Use your own story.'),
  pv('Respect','credit and acknowledge','Not','copying sacred designs','Respectful practice.','Choose your own idea.')],
 's2-arts-y3-w24-l1': [pv('Grid','straight black lines','Cut-out','curvy bold shapes','Two artists, two styles.','Technique shapes style.'),
  pv('Name','artist, title, material','Effect','what it does for the viewer','Artist details and effect.','Name the effect.')],
 's2-arts-y3-w24-l2': [pv('Inspired by','use one idea','Mine','new subject and colours','Inspiration, not copying.','Make your own version.'),
  pv('Label','title and credit','Reflect','what I changed','Credit and reflect.','Credit the artist.')],
}

def create_all():
    create(LESSONS, VISUALS, 12)

if __name__ == '__main__':
    create_all()
